"""Build baseline settlement reconciliation in PostGIS."""
from pathlib import Path
from src.ingestion.reference_db_connection import reference_cursor
def build_settlement_reconciliation(connection):
 with reference_cursor(connection) as cur:
  cur.execute(Path(__file__).resolve().parents[2].joinpath('database','coverage_reconciliation.sql').read_text())
  cur.execute('DELETE FROM processed.settlement_coverage_reconciliation')
  cur.execute("""WITH e AS (SELECT settlement_id,COUNT(*) n,COALESCE(SUM(doses_administered),0) all_doses,COALESCE(SUM(doses_administered) FILTER (WHERE doses_administered<=target_population_under5),0) plausible_doses,BOOL_OR(doses_administered>target_population_under5) bad FROM raw.etally_records GROUP BY settlement_id) INSERT INTO processed.settlement_coverage_reconciliation SELECT s.settlement_id,s.settlement_name,s.ward_code,s.ward_name,s.lga_name,v.visit_classification,v.confidence_class,CASE WHEN COALESCE(e.n,0)>0 THEN 'reported' ELSE 'no e-tally report' END,COALESCE(e.n,0),COALESCE(e.all_doses,0),COALESCE(e.plausible_doses,0),COALESCE(e.bad,FALSE),CASE WHEN v.visit_classification='visited' AND COALESCE(e.n,0)>0 THEN 'GPS visited / e-tally reported' WHEN v.visit_classification='visited' THEN 'GPS visited / no e-tally report' WHEN v.visit_classification='unvisited' AND COALESCE(e.n,0)>0 THEN 'GPS unvisited / e-tally reported' WHEN v.visit_classification='unvisited' THEN 'GPS unvisited / no e-tally report' WHEN COALESCE(e.n,0)>0 THEN 'GPS ambiguous / e-tally reported' ELSE 'GPS ambiguous / no e-tally report' END,(v.visit_classification<>'ambiguous' AND ((v.visit_classification='visited')<>(COALESCE(e.n,0)>0))),NULL FROM raw.settlements s JOIN processed.settlement_visit_summaries v ON v.settlement_id=s.settlement_id AND v.scenario_name='baseline_30m' LEFT JOIN e ON e.settlement_id=s.settlement_id""")
